// Modifier calculates the ability modifier for a given ability score.
// The modifier is the score minus 10, divided by 2, rounded down.
func Modifier(score int) int {
	diff := score - 10
	if diff < 0 {
		// Go integer division truncates toward zero, so adjust to round down.
		return (diff - 1) / 2
	}
	return diff / 2
}

// Ability uses randomness to generate the score for an ability.
// It rolls four 6-sided dice and returns the sum of the largest three.
func Ability() int {
	dice := make([]int, 4)
	for i := range dice {
		dice[i] = rand.Intn(6) + 1
	}
	sort.Ints(dice)
	return dice[1] + dice[2] + dice[3]
}

// GenerateCharacter creates a new Character with random scores for abilities.
// Hitpoints are 10 plus the constitution modifier.
func GenerateCharacter() Character {
	character := Character{
		Strength:     Ability(),
		Dexterity:    Ability(),
		Constitution: Ability(),
		Intelligence: Ability(),
		Wisdom:       Ability(),
		Charisma:     Ability(),
	}
	character.Hitpoints = 10 + Modifier(character.Constitution)
	return character
}
